WITH joined AS (SELECT src.*, b.browser, b.country, b.device FROM web_events src INNER JOIN sessions b ON src.session_id = b.id) SELECT DATE_TRUNC('YEAR', event_time) AS year_start, DATE_TRUNC('QUARTER', event_time) AS quarter_start, DATE_TRUNC('MONTH', event_time) AS activity_month, APPROX_PERCENTILE(duration_sec, ARRAY(0.25, 0.5, 0.75)) AS duration_sec_quartiles, ROUND(SUM(duration_sec) / NULLIF(COUNT(CASE WHEN device = 'desktop' THEN 1 END), 0), 2) AS duration_sec_per_desktop, APPROX_PERCENTILE(duration_sec, ARRAY(0.25, 0.5, 0.75)) AS duration_sec_quartiles_2, SUM(CASE WHEN event_type = 'add_to_cart' THEN duration_sec ELSE 0 END) AS add_to_cart_duration_sec FROM joined GROUP BY ROLLUP (DATE_TRUNC('YEAR', event_time), DATE_TRUNC('QUARTER', event_time), DATE_TRUNC('MONTH', event_time));
